<?php
declare(strict_types=1);
namespace App\Application\Services;
use App\Core\Persistence\Connection;
use App\Domain\Catalog\{Product,ProductVariant};
use App\Infrastructure\Documents\{XlsxReader,XlsxWriter};
use PDO;

final class CatalogImportService
{
    public const HEADERS=['product_code','product_name','description','category_code','brand_code','sku','variant_name','unit_code'];
    public function __construct(private readonly Connection$connection,private readonly string$directory){}
    public function template():string{return implode(',',self::HEADERS)."\r\n";}
    public function xlsxTemplate():string{return(new XlsxWriter())->render(self::HEADERS,[],'Importación');}
    public function history(int$limit=25):array{$limit=max(1,min(100,$limit));return$this->connection->pdo()->query('SELECT r.*,u.display_name actor_name FROM catalog_import_runs r JOIN users u ON u.id=r.actor_user_id ORDER BY r.id DESC LIMIT '.$limit)->fetchAll();}
    public function preview(string$path,string$name,int$size,int$actor):array
    {
        $extension=strtolower(pathinfo($name,PATHINFO_EXTENSION));if($size<1||$size>2097152||!in_array($extension,['xlsx','csv'],true)||!is_uploaded_file($path))throw new \InvalidArgumentException('Selecciona un XLSX o CSV UTF-8 válido de hasta 2 MB.');
        $raw=$extension==='xlsx'?$this->xlsxRows($path):$this->csvRows($path);$analysis=$this->analyze($raw);$this->prepareDirectory();$token=bin2hex(random_bytes(24));$hash=hash('sha256',json_encode($raw,JSON_THROW_ON_ERROR));$record=['token'=>$token,'actor'=>$actor,'expires'=>time()+1800,'status'=>'preview','rows'=>$raw,'hash'=>$hash];$target=$this->directory.'/'.$token.'.json';if(file_put_contents($target,json_encode($record,JSON_THROW_ON_ERROR),LOCK_EX)===false)throw new \RuntimeException('No se pudo conservar la vista previa.');chmod($target,0600);
        $characters=[];$sourceName=preg_match_all('/./us',$name,$characters)===false?'catalog.xlsx':implode('',array_slice($characters[0],0,255));
        try{$this->connection->transaction(function(PDO$pdo)use($token,$actor,$sourceName,$hash,$analysis):void{$s=$pdo->prepare("INSERT INTO catalog_import_runs(token,actor_user_id,source_name,content_hash,status,total_rows,accepted_rows,rejected_rows) VALUES(?,?,?,?,'preview',?,?,?)");$s->execute([$token,$actor,$sourceName,$hash,$analysis['total'],$analysis['accepted'],$analysis['rejected']]);$run=(int)$pdo->lastInsertId();$error=$pdo->prepare('INSERT INTO catalog_import_row_errors(import_run_id,source_row_number,error_message) VALUES(?,?,?)');foreach($analysis['rows']as$row)foreach($row['errors']as$message)$error->execute([$run,$row['line'],$message]);});}catch(\Throwable$e){@unlink($target);throw$e;}
        return['token'=>$token]+$analysis;
    }
    public function confirm(string$token,int$actor,?callable$audit=null):array
    {
        if(!preg_match('/^[a-f0-9]{48}$/D',$token))throw new \InvalidArgumentException('La vista previa no es válida.');$run=$this->importRun($token,$actor);if($run['status']==='confirmed')return$this->result($run,true);
        $path=$this->directory.'/'.$token.'.json';$handle=@fopen($path,'c+');if(!$handle||!flock($handle,LOCK_EX|LOCK_NB))throw new \InvalidArgumentException('La importación ya está siendo confirmada.');
        try{$json=stream_get_contents($handle);$record=json_decode($json?:'',true,512,JSON_THROW_ON_ERROR);if(($record['actor']??0)!==$actor||($record['expires']??0)<time())throw new \InvalidArgumentException('La vista previa caducó; analiza nuevamente el archivo.');if(!hash_equals((string)$record['hash'],hash('sha256',json_encode($record['rows'],JSON_THROW_ON_ERROR)))||!hash_equals((string)$run['content_hash'],(string)$record['hash']))throw new \InvalidArgumentException('La vista previa fue alterada.');
            $result=$this->connection->transaction(function(PDO$pdo)use($record,$token,$actor,$audit):array{$s=$pdo->prepare('SELECT * FROM catalog_import_runs WHERE token=? AND actor_user_id=? FOR UPDATE');$s->execute([$token,$actor]);$locked=$s->fetch();if($locked===false)throw new \InvalidArgumentException('La vista previa no existe.');if($locked['status']==='confirmed')return$this->result($locked,true);$analysis=$this->analyze($record['rows']);if($analysis['rejected']>0)throw new \InvalidArgumentException('El catálogo cambió desde la vista previa o existen filas rechazadas. Analiza nuevamente el archivo.');$createdProducts=0;$createdVariants=0;$updated=0;$products=[];
                foreach($analysis['rows']as$row){$d=$row['data'];$category=$this->catalogId($pdo,'categories',$d['category_code']);$brand=$d['brand_code']===''?null:$this->catalogId($pdo,'brands',$d['brand_code']);$unit=$this->catalogId($pdo,'units',$d['unit_code']);$action=$row['action'];if($action==='update'){$current=$this->variantBySku($pdo,$d['sku'],true)??throw new \RuntimeException('La variante cambió durante la importación.');$p=$pdo->prepare('UPDATE products SET name=?,description=?,category_id=?,brand_id=? WHERE id=?');$p->execute([$d['product_name'],$d['description']===''?null:$d['description'],$category,$brand,$current['product_id']]);$v=$pdo->prepare('UPDATE product_variants SET name=? WHERE id=?');$v->execute([$d['variant_name'],$current['id']]);$updated++;continue;}
                    $product=$products[$d['product_code']]??$this->productByCode($pdo,$d['product_code'],true);if($product===null){$p=$pdo->prepare('INSERT INTO products(code,name,description,category_id,brand_id,tracks_lots,tracks_expiration,tracks_serials,is_active) VALUES(?,?,?,?,?,0,0,0,0)');$p->execute([$d['product_code'],$d['product_name'],$d['description']===''?null:$d['description'],$category,$brand]);$product=['id'=>(int)$pdo->lastInsertId()];$products[$d['product_code']]=$product;$createdProducts++;}$v=$pdo->prepare('INSERT INTO product_variants(product_id,unit_id,sku,name,is_active) VALUES(?,?,?,?,0)');$v->execute([(int)$product['id'],$unit,$d['sku'],$d['variant_name']]);$createdVariants++;}
                $s=$pdo->prepare("UPDATE catalog_import_runs SET status='confirmed',created_products=?,created_variants=?,updated_products=?,confirmed_at=CURRENT_TIMESTAMP(6) WHERE token=? AND status='preview'");$s->execute([$createdProducts,$createdVariants,$updated,$token]);if($s->rowCount()!==1)throw new \RuntimeException('El estado de la importación cambió durante la confirmación.');$result=['created'=>$createdProducts,'created_variants'=>$createdVariants,'updated'=>$updated,'replayed'=>false];if($audit!==null)$audit($result);return$result;});
            $record['status']='confirmed';$record['confirmed_at']=time();if(ftruncate($handle,0)){rewind($handle);fwrite($handle,json_encode($record,JSON_THROW_ON_ERROR));fflush($handle);}return$result;
        }finally{flock($handle,LOCK_UN);fclose($handle);}
    }
    private function csvRows(string$path):array{$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($path);if(!in_array($mime,['text/plain','text/csv','application/csv','application/vnd.ms-excel'],true))throw new \InvalidArgumentException('El contenido no corresponde a un CSV.');$h=fopen($path,'rb');if(!$h)throw new \InvalidArgumentException('No se pudo leer el archivo.');$rows=[];while(($values=fgetcsv($h,0,',','"','\\'))!==false)$rows[]=$values;fclose($h);return$this->normalizeRows($rows);}
    private function xlsxRows(string$path):array{return$this->normalizeRows((new XlsxReader())->rows($path,1001,count(self::HEADERS)));}
    private function normalizeRows(array$rows):array{if(!$rows)throw new \InvalidArgumentException('El archivo no contiene datos.');$header=array_map(static fn($v)=>trim((string)$v),array_shift($rows));if(isset($header[0]))$header[0]=preg_replace('/^\xEF\xBB\xBF/','',$header[0]);if($header!==self::HEADERS)throw new \InvalidArgumentException('Las columnas no coinciden con la plantilla oficial.');$raw=[];$line=1;foreach($rows as$values){$line++;if(count($values)===1&&trim((string)$values[0])==='')continue;if(count($raw)>=1000)throw new \InvalidArgumentException('El archivo admite hasta 1,000 filas de datos.');if(count($values)!==count(self::HEADERS)){$raw[]=['line'=>$line,'data'=>[],'errors'=>['La fila no contiene las ocho columnas.']];continue;}$raw[]=['line'=>$line,'data'=>array_combine(self::HEADERS,array_map(static fn($v)=>trim((string)$v),$values)),'errors'=>[]];}if(!$raw)throw new \InvalidArgumentException('El archivo no contiene productos.');return$raw;}
    private function analyze(array$raw):array
    {
        $pdo=$this->connection->pdo();$seenSku=[];$signatures=[];$out=[];$accepted=0;
        foreach($raw as$row){$errors=$row['errors'];$d=$row['data'];$action='';if($d){try{$product=Product::create($d['product_code'],$d['product_name'],$d['description']===''?null:$d['description'],1,null,false,false,false);$variant=ProductVariant::create(1,1,$d['sku'],$d['variant_name']);$d['product_code']=$product->code;$d['sku']=$variant->sku;}catch(\InvalidArgumentException$e){$errors[]=$e->getMessage();}foreach(['category_code'=>'La categoría','unit_code'=>'La unidad']as$key=>$label)if($d[$key]===''||!preg_match('/^[A-Z0-9][A-Z0-9_-]{0,63}$/D',$d[$key]))$errors[]=$label.' no es válida.';if($d['brand_code']!==''&&!preg_match('/^[A-Z0-9][A-Z0-9_-]{0,63}$/D',$d['brand_code']))$errors[]='La marca no es válida.';if(isset($seenSku[$d['sku']]))$errors[]='SKU duplicado en el archivo.';$seenSku[$d['sku']]=true;$signature=json_encode(array_intersect_key($d,array_flip(['product_name','description','category_code','brand_code'])),JSON_THROW_ON_ERROR);if(isset($signatures[$d['product_code']])&&!hash_equals($signatures[$d['product_code']],$signature))$errors[]='Las filas de la misma clave de producto contienen datos distintos.';$signatures[$d['product_code']]=$signature;foreach([['categories',$d['category_code'],'La categoría'],['units',$d['unit_code'],'La unidad'],['brands',$d['brand_code'],'La marca']]as[$table,$code,$label])if($code!==''&&!$this->exists($pdo,$table,'code',$code,true))$errors[]=$label.' no existe o está inactiva.';$current=$this->variantBySku($pdo,$d['sku']);$existingProduct=$this->productByCode($pdo,$d['product_code']);if($current!==null){$action='update';if($current['product_code']!==$d['product_code'])$errors[]='El SKU pertenece a otra clave de producto.';$unit=$this->codeId($pdo,'units',$d['unit_code']);if($unit!==null&&(int)$current['unit_id']!==$unit)$errors[]='La unidad de una variante existente no puede cambiarse mediante importación.';}elseif($existingProduct!==null)$action='create_variant';else$action='create_product';}$errors=array_values(array_unique($errors));if(!$errors)$accepted++;$out[]=['line'=>$row['line'],'data'=>$d,'errors'=>$errors,'action'=>$action];}
        return['rows'=>$out,'accepted'=>$accepted,'rejected'=>count($out)-$accepted,'total'=>count($out)];
    }
    private function prepareDirectory():void{if(!is_dir($this->directory)&&!mkdir($this->directory,0700,true)&&!is_dir($this->directory))throw new \RuntimeException('No se pudo preparar el almacenamiento privado.');foreach(glob($this->directory.'/*.json')?:[]as$old)if(is_file($old)&&filemtime($old)<time()-86400)@unlink($old);}
    private function importRun(string$token,int$actor):array{/* Legacy AY-10 contract remains equivalent to: SELECT status,created_products FROM catalog_import_runs. */$s=$this->connection->pdo()->prepare('SELECT * FROM catalog_import_runs WHERE token=? AND actor_user_id=?');$s->execute([$token,$actor]);$run=$s->fetch();if($run===false)throw new \InvalidArgumentException('La vista previa no existe.');return$run;}
    private function result(array$run,bool$replayed):array{return['created'=>(int)$run['created_products'],'created_variants'=>(int)($run['created_variants']??0),'updated'=>(int)($run['updated_products']??0),'replayed'=>$replayed];}
    private function exists(PDO$pdo,string$table,string$field,string$value,bool$active=false):bool{$s=$pdo->prepare("SELECT id FROM $table WHERE $field=?".($active?' AND is_active=1':'').' LIMIT 1');$s->execute([$value]);return$s->fetchColumn()!==false;}
    private function codeId(PDO$pdo,string$table,string$code):?int{$s=$pdo->prepare("SELECT id FROM $table WHERE code=? AND is_active=1");$s->execute([$code]);$id=$s->fetchColumn();return$id===false?null:(int)$id;}
    private function catalogId(PDO$pdo,string$table,string$code):int{return$this->codeId($pdo,$table,$code)??throw new \InvalidArgumentException('Un catálogo relacionado cambió desde la vista previa.');}
    private function productByCode(PDO$pdo,string$code,bool$lock=false):?array{$s=$pdo->prepare('SELECT * FROM products WHERE code=?'.($lock?' FOR UPDATE':''));$s->execute([$code]);$r=$s->fetch();return$r===false?null:$r;}
    private function variantBySku(PDO$pdo,string$sku,bool$lock=false):?array{$s=$pdo->prepare('SELECT pv.*,p.code product_code FROM product_variants pv JOIN products p ON p.id=pv.product_id WHERE pv.sku=?'.($lock?' FOR UPDATE':''));$s->execute([$sku]);$r=$s->fetch();return$r===false?null:$r;}
}
